func TestDatabaseServerOrderingAndDeduplication(t *testing.T) {
	first := NewDatabaseServerV3("db", nil, DatabaseServerSpecV3{HostID: "host-b"})
	second := NewDatabaseServerV3("db", nil, DatabaseServerSpecV3{HostID: "host-a"})
	third := NewDatabaseServerV3("other", nil, DatabaseServerSpecV3{HostID: "host-c"})
	servers := []DatabaseServer{first, third, second}

	unique := DeduplicateDatabaseServers(servers)
	if len(unique) != 2 || unique[0] != first || unique[1] != third {
		t.Fatalf("deduplication changed first occurrence order: %v", unique)
	}
	if !strings.Contains(first.String(), "HostID=host-b") {
		t.Fatalf("server string does not include host ID: %s", first)
	}

	sort.Sort(SortedDatabaseServers(servers))
	if servers[0] != second || servers[1] != first || servers[2] != third {
		t.Fatalf("unexpected server order: %v", servers)
	}
